<script setup lang="ts">
import {ref,computed,onMounted,onUnmounted,watch} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {ArrowLeft,ArrowUpRight,Search,RefreshCw,Square,FileText,Clock3,Check,Download} from 'lucide-vue-next'
import {useLocal} from '../stores/local'
import type {Document,MutationReceipt} from '../domain/local-contract'
import {taskModules,taskStates,filterTaskIndex,taskBody,type TaskModule,type TaskState,type TaskIndexEntry,type TaskBody} from '../task-runtime/task-index'
import {localTaskIndex,stopTaskFromCenter} from '../task-runtime/task-center'
import Sheet from '../components/Sheet.vue'
const store=useLocal(),route=useRoute(),router=useRouter(),rows=ref<TaskIndexEntry[]>([]),error=ref(''),loading=ref(true),refreshing=ref(false),busy=ref(false),notice=ref(''),page=ref(0)
const query=ref(typeof route.query.search==='string'?route.query.search:''),module=ref<TaskModule|'all'>(typeof route.query.module==='string'&&Object.hasOwn(taskModules,route.query.module)?route.query.module as TaskModule:'all'),state=ref<TaskState|'all'>(typeof route.query.state==='string'&&Object.hasOwn(taskStates,route.query.state)?route.query.state as TaskState:'all')
const selectedId=ref(typeof route.query.task==='string'?route.query.task:''),selected=ref<TaskIndexEntry|null>(null),body=ref<TaskBody|null>(null),receipts=ref<MutationReceipt[][]>([]),detailLoading=ref(false),detailError=ref('')
const filtered=computed(()=>filterTaskIndex(rows.value,query.value,module.value,state.value)),visible=computed(()=>filtered.value.slice(page.value*30,page.value*30+30)),pending=computed(()=>rows.value.filter(row=>!['completed','cancelled'].includes(row.state)).length)
let disposed=false,epoch=0,detailEpoch=0,detailRevision=0,timer:ReturnType<typeof setTimeout>|null=null,poll:ReturnType<typeof setInterval>|null=null
const active=(vault:typeof store.vault)=>!disposed&&store.vault===vault&&!!vault?.unlocked
function clear(){epoch++;detailEpoch++;rows.value=[];selected.value=null;body.value=null;receipts.value=[];error.value='';detailError.value='';notice.value='';loading.value=false;refreshing.value=false;detailRevision=0}
async function load(){const vault=store.vault,ticket=++epoch;if(!vault){clear();return}refreshing.value=true;try{const result=await localTaskIndex(vault);if(!active(vault)||ticket!==epoch)return;rows.value=result;error.value='';page.value=Math.min(page.value,Math.max(0,Math.ceil(filtered.value.length/30)-1));if(selectedId.value){const current=result.find(r=>r.id===selectedId.value);selected.value=current||null;if(!current){body.value=null;receipts.value=[];detailError.value='这个任务已删除或无法打开'}else if(detailRevision!==current.revision)await loadDetail(current)}}catch(e){if(active(vault)&&ticket===epoch)error.value='记录读取失败：'+(e as Error).message}finally{if(active(vault)&&ticket===epoch){loading.value=false;refreshing.value=false}}}
async function loadDetail(row:TaskIndexEntry){const vault=store.vault,ticket=++detailEpoch;if(!vault)return;detailLoading.value=true;detailError.value='';try{const doc:Document|null=await vault.read(row.id);if(!doc||doc.kind!==row.kind)throw Error('这个任务已删除或无法打开');if(!active(vault)||ticket!==detailEpoch||selectedId.value!==row.id)return;body.value=taskBody(doc);detailRevision=doc.revision;try{const saved=await vault.documentReceipts(row.id);if(active(vault)&&ticket===detailEpoch&&selectedId.value===row.id)receipts.value=saved}catch{if(active(vault)&&ticket===detailEpoch){receipts.value=[];detailError.value='保存回执暂时无法读取，已保存文字仍然保留'}}}catch(e){if(active(vault)&&ticket===detailEpoch){body.value=null;receipts.value=[];detailError.value=(e as Error).message}}finally{if(active(vault)&&ticket===detailEpoch)detailLoading.value=false}}
function destination(id:string){return {path:route.path,query:{task:id,search:query.value||undefined,module:module.value==='all'?undefined:module.value,state:state.value==='all'?undefined:state.value}}}
async function close(){await router.replace({path:route.path,query:{...route.query,task:undefined}})}
async function stop(){const vault=store.vault,row=selected.value;if(!vault||!row||busy.value)return;busy.value=true;notice.value='';detailError.value='';try{const result=await stopTaskFromCenter(vault,row.id);if(active(vault)){await load();if(active(vault))notice.value=result.state==='cancelled'?(row.type==='video'?'已停止本地等待，供应商任务可在来源页面查询':'已停止，收到的内容保留'):'请求状态已更新，收到的内容保留'}}catch(e){if(active(vault)){await load();if(active(vault))detailError.value=(e as Error).message}}finally{if(active(vault))busy.value=false}}
function download(){if(!body.value||!selected.value)return;const output=body.value.sections.map(s=>s.title+'\n\n'+s.text).join('\n\n'),url=URL.createObjectURL(new Blob([output],{type:'text/plain;charset=utf-8'})),link=document.createElement('a');link.href=url;link.download=selected.value.title.replace(/[\\/:*?"<>|]/g,'-').slice(0,80)+'.txt';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function changed(event:Event){const vault=store.vault,detail=(event as CustomEvent<{vaultId:string}>).detail;if(!active(vault)||detail?.vaultId!==vault?.id)return;if(timer)clearTimeout(timer);timer=setTimeout(()=>void load(),100)}
function date(value:string){return Number.isFinite(Date.parse(value))?new Date(value).toLocaleString():'日期未知'}
watch([query,module,state],()=>page.value=0)
watch(()=>store.vault,()=>{clear();if(store.vault){loading.value=true;void load()}},{flush:'sync'})
onMounted(()=>{void load();window.addEventListener('reader-private-commit',changed);window.addEventListener('reader-local-locked',clear);poll=setInterval(()=>{if(!refreshing.value)void load()},5000)})
onUnmounted(()=>{disposed=true;clear();window.removeEventListener('reader-private-commit',changed);window.removeEventListener('reader-local-locked',clear);if(timer)clearTimeout(timer);if(poll)clearInterval(poll)})
</script>
<template>
 <section class="final-task-center">
  <header class="final-page-heading"><div class="final-heading-copy"><RouterLink to="/local/settings" class="final-text-link"><ArrowLeft :size="17"/>我的</RouterLink><h1>任务中心</h1><span class="final-subtle">{{rows.length}} 项 · {{pending}} 项待处理</span></div><button class="final-icon-button" aria-label="刷新任务记录" :disabled="refreshing" @click="load"><RefreshCw :size="20"/></button></header>
  <div class="task-filters"><label class="task-search"><Search :size="18"/><input v-model="query" aria-label="搜索任务" placeholder="名称、来源或模型" maxlength="200"></label><select v-model="module" aria-label="任务类型"><option value="all">全部类型</option><option v-for="(label,id) in taskModules" :key="id" :value="id">{{label}}</option></select><select v-model="state" aria-label="任务状态"><option value="all">全部状态</option><option v-for="(label,id) in taskStates" :key="id" :value="id">{{label}}</option></select></div>
  <p v-if="error" role="alert" class="final-error">{{error}}</p><p v-if="loading" role="status">正在读取记录…</p>
  <div v-else-if="!filtered.length" class="final-empty"><Clock3 :size="32"/><h2>{{rows.length?'没有匹配的任务':'还没有任务'}}</h2><RouterLink v-if="!rows.length" to="/local/library" class="final-text-link">回到书架<ArrowUpRight :size="16"/></RouterLink></div>
  <ul v-else class="task-list" aria-label="任务记录"><li v-for="row in visible" :key="row.id"><RouterLink class="task-row" :to="destination(row.id)"><span class="task-icon"><Check v-if="row.state==='completed'" :size="20"/><Clock3 v-else-if="['queued','active','unknown'].includes(row.state)" :size="20"/><FileText v-else :size="20"/></span><span class="task-copy"><strong>{{row.title}}</strong><small>{{taskModules[row.module]}}<template v-if="row.sourceTitle"> · {{row.sourceTitle}}</template><template v-if="row.model"> · {{row.model}}</template></small><small>{{date(row.updatedAt)}}</small></span><span class="task-state" :class="'is-'+row.state">{{taskStates[row.state]}}<small v-if="row.historical">恢复记录</small></span></RouterLink></li></ul>
  <nav v-if="filtered.length>30" class="task-pagination" aria-label="任务分页"><button :disabled="!page" @click="page--">上一页</button><span>{{page+1}} / {{Math.ceil(filtered.length/30)}}</span><button :disabled="(page+1)*30>=filtered.length" @click="page++">下一页</button></nav>
  <Sheet v-if="selectedId" :title="selected?.title||'任务记录'" @close="close">
   <p v-if="detailError" class="final-error" role="alert">{{detailError}}</p><p v-if="detailLoading" role="status">正在读取内容与回执…</p>
   <template v-if="selected"><div class="task-detail-summary"><span class="task-state" :class="'is-'+selected.state">{{taskStates[selected.state]}}</span><small>{{taskModules[selected.module]}} · {{date(selected.createdAt)}}</small></div><p v-if="selected.error" class="final-error">{{selected.error}}</p><p v-if="notice" role="status" class="final-subtle">{{notice}}</p>
    <div class="task-detail-actions"><RouterLink v-if="selected.destination" class="final-primary" :to="selected.destination">回到来源<ArrowUpRight :size="17"/></RouterLink><span v-else class="final-subtle">来源已删除或无法定位</span><button v-if="selected.canStop" :disabled="busy" @click="stop"><Square :size="16"/>停止</button><button v-if="body?.sections.length" @click="download"><Download :size="16"/>导出文字</button></div>
    <div v-if="selected.model" class="task-usage"><span>{{selected.model}}</span><small>请求尝试 {{selected.attempts===null?'查看关联任务':selected.attempts}} · 输入 {{selected.input===null?'未知':selected.input}} · 输出 {{selected.output===null?'未知':selected.output}} token</small></div>
    <div v-if="body" class="task-body"><article v-for="(section,i) in body.sections" :key="i"><h2>{{section.title}}</h2><p>{{section.text}}</p></article><p v-if="!body.sections.length&&!body.assetId&&!detailLoading" class="final-subtle">这项记录没有可查看的文字</p><RouterLink v-if="body.assetId" class="final-text-link" :to="{path:'/local/gallery',query:{asset:body.assetId}}">查看已保存素材<ArrowUpRight :size="16"/></RouterLink><RouterLink v-for="id in body.children" :key="id" class="final-text-link" :to="destination(id)">查看关联任务<ArrowUpRight :size="16"/></RouterLink>
     <details v-if="body.requestIds.length"><summary>供应商请求号</summary><p v-for="id in body.requestIds" :key="id" class="task-code">{{id}}</p></details><details v-if="body.events.length"><summary>状态记录</summary><p v-for="(event,i) in body.events" :key="i">{{date(event.at)}} · {{event.label}}</p></details>
    </div><details class="task-receipts"><summary>本地保存回执 · {{receipts.length}}</summary><p v-if="!receipts.length" class="final-subtle">暂无已提交回执</p><article v-for="receipt in receipts" :key="receipt[0]!.operationId"><small>{{date(receipt[0]!.committedAt)}}</small><p class="task-code">{{receipt[0]!.operationId}}</p><p v-for="saved in receipt" :key="saved.documentId" class="task-code">{{saved.documentId}} · 版本 {{saved.revision}}</p></article></details>
   </template>
  </Sheet>
 </section>
</template>
<style scoped>
.task-filters{display:grid;grid-template-columns:minmax(160px,1fr) 150px 150px;gap:10px;margin:20px 0 24px}.task-search{position:relative;display:flex;align-items:center}.task-search svg{position:absolute;left:14px;color:var(--quiet)}.task-search input{width:100%;padding-left:42px}.task-list{list-style:none;padding:0;margin:0;border-top:1px solid var(--edge)}.task-list li{border-bottom:1px solid var(--edge)}.task-row{display:flex;align-items:center;gap:16px;min-height:102px;padding:18px 8px;color:var(--ink);text-decoration:none;border-radius:10px;transition:background .16s}.task-row:hover{background:var(--canvas)}.task-icon{width:44px;height:44px;border-radius:50%;display:grid;place-items:center;flex:none;background:var(--accent-soft);color:var(--accent)}.task-copy{display:grid;gap:6px;min-width:0;flex:1}.task-copy strong{font-size:17px;overflow-wrap:anywhere;font-weight:550}.task-copy small{color:var(--quiet);overflow-wrap:anywhere}.task-state{font-size:13px;color:var(--quiet);white-space:nowrap;display:grid;gap:4px}.task-state small{font-size:11px}.task-state.is-active,.task-state.is-queued,.task-state.is-approval{color:var(--accent)}.task-state.is-failed,.task-state.is-unknown{color:var(--danger)}.task-pagination{display:flex;align-items:center;justify-content:center;gap:20px;margin-top:24px}.task-detail-summary{display:flex;align-items:center;gap:14px;margin-bottom:20px;flex-wrap:wrap}.task-detail-summary small,.task-usage small{color:var(--quiet)}.task-detail-actions{display:flex;gap:10px;flex-wrap:wrap;margin:20px 0}.task-detail-actions button,.task-detail-actions a{min-height:44px}.task-usage{display:grid;gap:8px;padding:16px 0;border-top:1px solid var(--edge);border-bottom:1px solid var(--edge)}.task-body article{margin:26px 0}.task-body h2{font-size:17px}.task-body article p{white-space:pre-wrap;overflow-wrap:anywhere;line-height:1.9}.task-body details{margin:16px 0}.task-receipts{margin-top:24px;padding-top:20px;border-top:1px solid var(--edge)}.task-receipts article{padding:16px 0;border-bottom:1px solid var(--edge)}.task-code{font-family:ui-monospace,monospace;font-size:12px;overflow-wrap:anywhere}.task-body> a{margin:12px 0;display:flex}@media(max-width:600px){.task-filters{grid-template-columns:1fr 1fr;gap:8px}.task-search{grid-column:1/-1}.task-row{gap:12px;min-height:104px;padding:16px 0}.task-icon{width:36px;height:36px}.task-copy strong{font-size:16px}.task-copy small{font-size:12px}.task-state{font-size:12px}}
.task-body summary,.task-receipts>summary{min-height:44px;padding:10px 0;line-height:24px;cursor:pointer}.task-body summary:focus-visible,.task-receipts>summary:focus-visible{outline:2px solid var(--accent);outline-offset:4px;border-radius:4px}
</style>
